#include <Adafruit_SHT31.h>

Adafruit_SHT31 sht31 = Adafruit_SHT31();

void setup() {
  Serial.begin(115200);
  if (!sht31.begin(0x44)) {
    Serial.println("SHT31 not found - check SDA/SCL (address 0x44, or 0x45 with ADR high)");
    while (true) delay(10);
  }
}

void loop() {
  float t = sht31.readTemperature();
  float h = sht31.readHumidity();
  Serial.print("Temperature: ");
  Serial.print(t);
  Serial.print(" C, humidity: ");
  Serial.print(h);
  Serial.println(" %");
  delay(1000);
}
